// Scaffolding generated by Claude
import { api } from "../api";
import {logIn} from "@/context/authenticationSlice.ts";

export interface LoginRequest {
    username?: string;
    email?: string;
    password: string;
}

export interface AuthUser {
    _id: string;
    username: string;
    email: string;
    roles: string[];
}

export const authApi = api.injectEndpoints({
    endpoints: (builder) => ({
        login: builder.mutation<AuthUser, LoginRequest>({
            query: (credentials) => ({
                url: "/login",
                method: "POST",
                body: credentials,
            }),
            invalidatesTags: ["CurrentUser"],
            async onQueryStarted(_credentials, { dispatch, queryFulfilled }) {
                try {
                    const { data } = await queryFulfilled;
                    dispatch(logIn({ username: data.username, email: data.email, userId: data._id, roles: data.roles }));
                } catch {
                    // login failed — no dispatch needed, error surfaces via the mutation's own error state
                }
            },
        }),

        signUp: builder.mutation<AuthUser, LoginRequest>({
            query: (credentials) => ({
                url: "/signUp",
                method: "POST",
                body: credentials,
            }),
            invalidatesTags: ["CurrentUser", "User"],
            async onQueryStarted(_credentials, { dispatch, queryFulfilled }) {
                try {
                    const { data } = await queryFulfilled;
                    dispatch(logIn({ username: data.username, email: data.email, userId: data._id, roles: data.roles }));
                } catch {
                    // login failed — no dispatch needed, error surfaces via the mutation's own error state
                }
            },
        }),
    }),
});

export const {
    useLoginMutation,
} = authApi;